```js
const KNOWN = {
  a: 'alpha',
  b: 'bravo',
  c: 'charlie',
};

export async function listTools() {
  return [
    {
      name: 'batch_lookup',
      description: 'Look up multiple ids in one batch. Returns one result per id; missing ids do not abort the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            description: 'Non-empty array of id strings to look up, in input order.',
          },
        },
        required: ['ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'batch_lookup') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }
  // Validate arguments
  const keys = Object.keys(args);
  if (keys.length !== 1 || !keys.includes('ids')) {
    const err = new Error('Invalid arguments: expected exactly {ids: string[]}');
    err.code = -32602;
    throw err;
  }
  const { ids } = args;
  if (!Array.isArray(ids)) {
    const err = new Error('ids must be an array');
    err.code = -32602;
    throw err;
  }
  if (ids.length === 0) {
    const err = new Error('ids must be a non-empty array');
    err.code = -32602;
    throw err;
  }
  if (!ids.every((id) => typeof id === 'string')) {
    const err = new Error('ids must be an array of strings');
    err.code = -32602;
    throw err;
  }

  const results = ids.map((id) => {
    if (Object.prototype.hasOwnProperty.call(KNOWN, id)) {
      return { id, ok: true, value: KNOWN[id] };
    }
    return { id, ok: false, error: `Unknown id: ${id}` };
  });

  return {
    content: [{ type: 'text', text: JSON.stringify({ results }) }],
  };
}
```

Wait, regarding extra arguments: the task says "Reject invalid/extra arguments". My check `keys.length !== 1 || !keys.includes('ids')` handles this - if there are extra keys, length > 1, reject. If `ids` missing entirely, length 0 or different. Good.

But wait, what if args is `undefined`? The protocol passes `req.params.arguments||{}` so it's always an object. But `callTool` default `args = {}`. With `{}`, keys.length is 0, so it rejects with "expected exactly {ids: string[]}". Good.

